public enum TaskNodeKind: Sendable, Hashable {
    case method
    case task
    case thread
    case suspension
    case cycle
    static func read(_ pointer: UnsafeRawPointer, _ owner: RustOwner) -> Self {
        switch dh_tag_TaskNodeKind(pointer) {
        case 0: return .method
        case 1: return .task
        case 2: return .thread
        case 3: return .suspension
        case 4: return .cycle
        default: preconditionFailure("Invalid Rust TaskNodeKind")
        }
    }
}

public enum TaskState: Sendable, Hashable {
    case running
