    case waiting
    case neverResumes
    case cycle
    case dropped
    static func read(_ pointer: UnsafeRawPointer, _ owner: RustOwner) -> Self {
        switch dh_tag_TaskState(pointer) {
        case 0: return .running
        case 1: return .queued
        case 2: return .waiting
        case 3: return .neverResumes
        case 4: return .cycle
        case 5: return .dropped
        default: preconditionFailure("Invalid Rust TaskState")
        }
    }
}

